Method.Implementation:

  set stDtTm = $ZDATETIME($HOROLOG,3, 1)
  set numFile = 0
  SET $ZSTORAGE=-1

  Set file=##class(%File).%New("/itf-share/itf-tmp/835sql.txt")
   Do file.Open("WSN")
   Do file.Close()

  &sql(DECLARE WPCursor CURSOR FOR select FileName, x12Data, ID into fNm, x12Data, x12Id from IHC_X12.Data835 where ApplicationReceiversCode is null)
  &sql(OPEN WPCursor)
        QUIT:(SQLCODE'=0)
   FOR { &sql(FETCH WPCursor)
        QUIT:SQLCODE 
        set x12Stream = ""
        set source = ""

        WRITE !, x12Id _", => " _ fNm _", <"_ $L(x12Data)
        if ($L(x12Data) < 10)
        {
	        WRITE !, "Open X12 Stream"
	        set obj = ##class(IHC.X12.Data835).%OpenId(x12Id)
	        WRITE !, x12Id _ "- " _ obj.x12DataStream
	        set x12Stream = obj.x12DataStream
	        if (x12Stream.Size > 0)
        	{
	        	set source = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(x12Stream)
        	}
        }
        else
        {
	        set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Data)
        }

		 if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
		 {		 	 
			Do ##class(IHC.ITF.ITFCOMMON.X12.StoreX12Data).ProcessX12Doc(source, fNm, x12Id)
			Do $INCREMENT(numFile) 
	     }
 }
  WRITE !, "# of X12 files stored: " _ numFile _". " _stDtTm _" -> " _ $ZDATETIME($HOROLOG,3, 1)
 QUIT
